// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *IssuedFinChargeMemoHeader) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, IssuedFinChargeMemoHeaderTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (no)`,
		fmt.Sprintf("%s$Issued_Fin_Charge_Memo_Header$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (customer_no, posting_date)`,
		fmt.Sprintf("%s$Issued_Fin_Charge_Memo_Header$customer_posting_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index customer_posting_date: %w", err)
	}
	var keys []sift.Key
	for _, spec := range issuedFinChargeMemoHeaderSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, IssuedFinChargeMemoHeaderTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, IssuedFinChargeMemoHeaderTableName, keys)
}

// issuedFinChargeMemoHeaderSIFTSpecs are the table's keys with sum_index_fields
func issuedFinChargeMemoHeaderSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *IssuedFinChargeMemoHeader) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := tables.CompanyTable(t.company, IssuedFinChargeMemoHeaderTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range issuedFinChargeMemoHeaderSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, IssuedFinChargeMemoHeaderTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: IssuedFinChargeMemoHeaderTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, IssuedFinChargeMemoHeaderTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

